VALUES
('alict_02201', 2, 'Number Systems & Data Representation', '00110111 This binary sequence splits into two 4 -bit 0011 and 0111. The first 0011, represents the decimal digit 3, and the second 0111, represents the decimal digit 7. Both digits fall within the valid BCD range of 0-9. 00110111 is a valid BCD representation', '["10011000", "01011001", "11001000", "10001001", "00110111 Each paragraph explains whether the given binary sequence is a valid BCD representation based on the rules of Binary-Coded Decimal encoding. The incorrect BCD value is identified as"]'::jsonb, 2, 'Correct answer: "01011001". This follows from converting/calculating the given number(s) using standard place-value (base) arithmetic.', NULL, NULL, 'medium', 'Number Systems & Data Representation', NULL, 2201, 'A/L Past Paper Series'),
('alict_02202', 2, 'Number Systems & Data Representation', 'Which of the following is the result of adding the hexadecimal numbers 3F216 and A4B16 ?', '["DRAM", "SRAM", "SDRAM", "CMOS", "EPROM"]'::jsonb, 1, 'Correct answer: "DRAM". This follows from converting/calculating the given number(s) using standard place-value (base) arithmetic.', NULL, NULL, 'medium', 'Number Systems & Data Representation', NULL, 2202, 'A/L Past Paper Series'),
